/** Tab shape used by order helpers (avoids circular import with BpTabGroup). */
export type BpTabOrderTarget = {
    id: string;
    disabled?: boolean;
    reorderable?: boolean;
};
/** Apply a saved id order while keeping fixed tabs at their definition positions. */
export declare function orderBpTabs<T extends BpTabOrderTarget>(tabs: readonly T[], order?: readonly string[]): T[];
